css:
.action-banner a[href*="frappe.utils.print_format.download_pdf"] {
    display: none !important;
}

p {
    font-size: 12pt; 
    font-family: Arial; 
    text-align: justify; 
    line-height: 2;
}

span {
    text-transform: uppercase;
    text-decoration: underline;
    font-weight: bold;
}
.head {
    font-size: 11pt; 
    font-style: italic;
    line-height: 1;
    padding-bottom: 60px;
}
.tab { 
    text-indent: 50px;
}
.name{
    line-height: 1;
    font-size: 14pt; 
    text-align: right;
}
.sig{
    line-height: 1;
    font-size: 11pt; 
    text-align: right;
}
.footer{
    line-height: 1;
    font-size: 10pt; 
    font-style: italic;
}
.pres{
    line-height: 1;
    padding-top: 40px;
    font-size: 12pt; 
    text-align: center;
}
.center{
    text-align: center;
    font-size: 14pt;
}

.single{
    text-align: center;
    font-size: 14pt;
    line-height: 1;
    padding-bottom: 60px;
}
.note{
    text-align: center;
    font-family: Times New Roman;
    line-height: 1;
    font-style: italic;
    font-size: 14pt;
}
.d-flex {
    display: -ms-flexbox;
    display: flex;
    padding-top: 40px;
}
.border {
    border: 1px solid black;
}

html:
{% set president=frappe.get_all("Employee", filters={"designation": "UNIVERSITY PRESIDENT (Office of the University President)"}, fields=["salutation","first_name","middle_name","last_name","custom_name_extension","designation","custom_preferred_post_nominal_titles"]) | list %}
{% set hr_director=frappe.get_all("Employee", filters={"designation": "DIRECTOR (Human Resource Development Office)"}, fields=["salutation","first_name","middle_name","last_name","custom_name_extension","designation","custom_preferred_post_nominal_titles"]) | list %}
{% set hr_oic=frappe.get_all("Employee", filters={"designation": "OIC (Human Resource Development Office)"}, fields=["salutation","first_name","middle_name","last_name","custom_name_extension","designation","custom_preferred_post_nominal_titles"]) | list %}

{% if doc.branch == "Main" %}
    {% if "College" in doc.custom_office or "Student Affairs and Services" in doc.custom_office or "Graduate Studies" in doc.custom_office %}
        {% set office_head=frappe.get_all("Employee", filters={"designation": "DEAN ("+ doc.custom_office + ")"}, fields=["salutation","first_name","middle_name","last_name","custom_name_extension","designation","custom_preferred_post_nominal_titles"]) | list %}
        {% set office_head_designation="Dean" %}
    {% elif "Accounting Office" in doc.custom_office or "Cashier's Office" in doc.custom_office or "Budget Office" in doc.custom_office %}
        {% set office_head=frappe.get_all("Employee", filters={"designation": "HEAD ("+ doc.custom_office + ")"}, fields=["salutation","first_name","middle_name","last_name","custom_name_extension","designation","custom_preferred_post_nominal_titles"]) | list %}
        {% set office_head_designation="Head" %}
    {% elif "Human Resource Development Office" in doc.custom_office %}
        {% set office_head=frappe.get_all("Employee", filters={"designation": "HEAD, REWARDS AND RECOGNITION UNIT ("+ doc.custom_office + ")"}, fields=["salutation","first_name","middle_name","last_name","custom_name_extension","designation","custom_preferred_post_nominal_titles"]) | list %}
        {% set office_head_designation="Head" %}
    {% elif "Office of the President" in doc.custom_office %}
        {% set office_head=frappe.get_all("Employee", filters={"designation": "UNIVERSITY PRESIDENT ("+ doc.custom_office + ")"}, fields=["salutation","first_name","middle_name","last_name","custom_name_extension","designation","custom_preferred_post_nominal_titles"]) | list %}
        {% set office_head_designation="University President" %}
    {% elif "Vice President" in doc.custom_office %}
        {% set office_head=frappe.get_all("Employee", filters={"designation": "VICE PRESIDENT ("+ doc.custom_office + ")"}, fields=["salutation","first_name","middle_name","last_name","custom_name_extension","designation","custom_preferred_post_nominal_titles"]) | list %}
        {% set office_head_designation="Vice President" %}
    {% else %}
        {% set office_head=frappe.get_all("Employee", filters={"designation": "DIRECTOR ("+ doc.custom_office + ")"}, fields=["salutation","first_name","middle_name","last_name","custom_name_extension","designation","custom_preferred_post_nominal_titles"]) | list %}
        {% set office_head_designation="Director" %}
    {% endif %}
{% elif doc.branch == "Dasmariñas"%}
    {% set office_head=frappe.get_all("Employee", filters={"designation": "CENTER ADMINISTRATOR ("+ doc.custom_office + ")"}, fields=["salutation","first_name","middle_name","last_name","custom_name_extension","designation","custom_preferred_post_nominal_titles"]) | list %}
    {% set office_head_designation="Center Administrator" %}
{% elif doc.branch == "Maragondon"%}
    {% set office_head=frappe.get_all("Employee", filters={"designation": "PRINCIPAL ("+ doc.branch + ")"}, fields=["salutation","first_name","middle_name","last_name","custom_name_extension","designation","custom_preferred_post_nominal_titles"]) | list %}
    {% set office_head_designation="Principal" %}
{% else %}
    {% set office_head=frappe.get_all("Employee", filters={"designation": "CAMPUS ADMINISTRATOR ("+ doc.branch + ")"}, fields=["salutation","first_name","middle_name","last_name","custom_name_extension","designation","custom_preferred_post_nominal_titles"]) | list %}
    {% set office_head_designation="Campus Administrator" %}

{% endif %}
{% set office_oic=frappe.get_all("Employee", filters={"designation": "OIC ("+ doc.custom_office + ")"}, fields=["salutation","first_name","middle_name","last_name","custom_name_extension","designation"]) | list %}
{% if not office_head and office_oic %}
    {% set office_head_designation="OIC" %}
{% endif %}

{% if doc.gender == "Male" %}
    {% set salutation = "MR" %}
{% else %}
    {% set salutation = "MS" %}
{% endif %}

{# {% extends 'templates/includes/forbidden.html' %} #}
{# {% block content %} #}
<div>
    <p class="head">
        <b>CS Form No. 4</b><br>
        Revised 2025
    </p>    							
    
    
    <p class="single">
        Republic of the Philippines<br>
        <u>{{doc.company|upper}}</u>
    </p>
    
    
    
    <p class="center"><b>CERTIFICATION OF ASSUMPTION TO DUTY</b></p>
    
    <p class="tab">
        This is to certify that <span>{{salutation}}. {{doc.employee_name + ' ' + doc.custom_name_extension if doc.custom_name_extension else doc.employee_name}}</span> has assumed the duties and responsibilities as <span>{{doc.custom_position}}</span> of <b><u>{{doc.company}}</u></b> effective _________________.<br>
    </p>
    <p class="tab">
        This certification is issued in connection with the issuance of the appointment of <span>{{salutation}}. {{doc.last_name + ' ' + doc.custom_name_extension if doc.custom_name_extension else doc.last_name}}</span> as <span>{{doc.custom_position}}.</span><br>
    </p>
    
    <p class="tab">
        Done this _____ day of __________ {{frappe.utils.get_datetime(frappe.utils.nowdate()).strftime('%Y')}} in <u>{{doc.company}}</u>. 
        <!--{{ frappe.format(frappe.utils.today(), {'fieldtype': 'Year'})}}-->
    </p>
    
    <div class="pull-right">
        <div class="pres">
            <div>   

                {% if office_head %} 
                    <b><u>{{office_head[0].first_name|upper +' '}} {{office_head[0].middle_name[0]|upper +'. ' if office_head[0].middle_name}} {{office_head[0].last_name + ' ' + office_head[0].custom_name_extension if office_head[0].custom_name_extension else office_head[0].last_name}}{{', ' + office_head[0].custom_preferred_post_nominal_titles if office_head[0].custom_preferred_post_nominal_titles}}</u></b>
                {% elif office_oic %} 
                    <b><u>{{office_oic[0].first_name|upper +' '}} {{office_oic[0].middle_name[0]|upper +'. ' if office_oic[0].middle_name}} {{office_oic[0].last_name + ' ' + office_oic[0].custom_name_extension if office_oic[0].custom_name_extension else office_oic[0].last_name}}{{', ' + office_oic[0].custom_preferred_post_nominal_titles if office_oic[0].custom_preferred_post_nominal_titles}}</u></b>
                {% endif %}

            </div>
            <!--<div>-->
            <!--    {% set company_abbreviation = frappe.db.get_value('Company', doc.company, 'abbr') %}-->
            <!--    {{ company_abbreviation }}-->
            <!--</div>-->
            <center>
                Head of Office/Department/Unit
            </center>
        </div>
    </div>						
    
    <p style="padding-top:120px;">Attested by:</p>
    
    
    <div class="pull-left" style="padding-bottom: 10px;">
        <div class="pres">
            {% if hr_director %} 
                <div><b><u>{{hr_director[0].first_name|upper +' '}} {{hr_director[0].middle_name[0]|upper +'. ' if hr_director[0].middle_name}} {{hr_director[0].last_name + ' ' + hr_director[0].custom_name_extension if hr_director[0].custom_name_extension else hr_director[0].last_name}} {{', ' + hr_director[0].custom_preferred_post_nominal_titles if hr_director[0].custom_preferred_post_nominal_titles else hr_director[0].custom_preferred_post_nominal_titles}}</u></b></div>
                <center>HRMO</center>
            {% elif hr_oic %} 
                <div><b><u>{{hr_oic[0].first_name|upper +' '}} {{hr_oic[0].middle_name[0]|upper +'. ' if hr_oic[0].middle_name}} {{hr_oic[0].last_name + ' ' + hr_oic[0].custom_name_extension if hr_oic[0].custom_name_extension else hr_oic[0].last_name}} {{', ' + hr_oic[0].custom_preferred_post_nominal_titles if hr_oic[0].custom_preferred_post_nominal_titles else hr_oic[0].custom_preferred_post_nominal_titles}}</u></b></div>
                <center>HRMO</center>
            {% endif %}
        </div>
        <div>
            <p style="padding-top:30px;">Date: _________________</p>
        </div>
    </div>
    
    <div class="clearfix"></div>
     
</div>
<div class="d-flex" >
        <div class="p-2 footer">201 file<br>
                    Admin<br>
                    COA<br>
                    CSC
        </div>
        <div class="p-3 ml-auto border note">For submission to CSC FO<br>
                                within 30 days from the<br>
                                date of assumption of the<br>
                                appointee
        </div>
</div>   
{# {% endblock %} #}
